def s(prompt,options,answer,why,context='สถานการณ์สมมติสำหรับฝึกในระบบ'):
    return scenario(prompt,context,options,answer,why,'อ่านเงื่อนไขและตรวจข้อมูลที่ให้ ก่อนเลือกคำตอบ')
def seq(prompt,ordered,why):
    # Reverse display order, never expose the reference order to the student client.
    return sequence(prompt,list(reversed(ordered)),list(reversed(range(len(ordered)))),why,'คิดว่าขั้นใดต้องเกิดก่อน แล้วตรวจลำดับทั้งหมด')
def classify(prompt,cards,categories,answer,why):
    return sort_task(prompt,cards,categories,answer,why,'พิจารณาบัตรทีละใบตามเกณฑ์ที่โจทย์กำหนด')
def worksheet(prompt,headers,rows,fields,answer,why):
    return dict(kind='worksheet',prompt=prompt,headers=headers,rows=rows,fields=fields,answer=answer,explanation=why,hint='ไล่นับหรือคำนวณทีละแถว แล้วตรวจผลรวมอีกครั้ง')
def picture(prompt,answer):
    return dict(kind='picture',prompt=prompt,size=3,categories=['ว่าง','วงกลม 🔵','สามเหลี่ยม 🔺','สี่เหลี่ยม 🟨'],cards=[f'แถว {r+1} คอลัมน์ {c+1}' for r in range(3) for c in range(3)],answer=answer,explanation='อ่านแถวเป็นแนวนอน คอลัมน์เป็นแนวตั้ง แล้วตรวจรูปในแต่ละช่องตามคำสั่ง ช่องอื่นต้องว่าง',hint='เริ่มนับแถวจากบน และคอลัมน์จากซ้าย')

ACTIVITIES=[]
def add(code,title,skill,lesson,example,tasks,reflection):
    chapter=int(code.split('.')[0]);name,unit,pdf,printed=CHAPTERS[chapter]
    ACTIVITIES.append(dict(code=code,title=title,unit=unit,chapter=chapter,chapter_title=name,pdf_page=pdf,printed_pages=printed,skill=skill,lesson=lesson,example=example,tasks=tasks,reflection=reflection))

