base_grid=[1,2,3,4,3,4,1,2,2,1,4,3,4,3,2,1]
def sudoku(blanks):
    return dict(kind='numbergrid',prompt='เติมเลข 1–4 ให้แต่ละแถว คอลัมน์ และกรอบ 2×2 มีเลขไม่ซ้ำ',size=4,givens=[0 if i in blanks else n for i,n in enumerate(base_grid)],answer=base_grid[:],hint='เริ่มจากแถวหรือคอลัมน์ที่เหลือช่องว่างน้อยที่สุด',explanation='ตรวจครบทั้งแถว คอลัมน์ และกรอบ 2×2 แต่ละกลุ่มต้องมี 1, 2, 3, 4 อย่างละหนึ่ง')
