EXTRA_MODES={'picture':('ศิลปะบนตาราง','เลือกรูปลงแต่ละช่องให้ตรงกับคำสั่ง ช่องอื่นให้ว่าง','ฝึกแปลคำสั่งเป็นภาพและตรวจตำแหน่งด้วยตนเอง'),'worksheet':('โต๊ะคำนวณข้อมูล','อ่านตารางแล้วกรอกผลคำนวณให้ครบทุกช่อง','คำนวณจากข้อมูลที่มองเห็นและตรวจผลรวม'),'numbergrid':('ปริศนาตารางตัวเลข','เติมเลข 1–4 ในช่องว่าง ตรวจทั้งแถว คอลัมน์ และกรอบ 2×2','ตัดตัวเลือกที่ขัดเงื่อนไขแทนการเดา')}
def extend_from_guide(existing):
    result=list(existing);last={u:next(l['id'] for l in reversed(existing) if l['unit']==u) for u in range(1,5)};counts={u:6 for u in range(1,5)}
    for offset,a in enumerate(ACTIVITIES,25):
        unit=a['unit'];counts[unit]+=1;mode=a['tasks'][0]['kind'];label,instructions,rationale=(MODE_INFO|EXTRA_MODES)[mode]
        questions=[q|{'id':f'guide-{offset}-{i}'} for i,q in enumerate(a['tasks'],1)]
        result.append(dict(id=offset,unit=unit,number=f'{unit}-{counts[unit]}',stage=counts[unit],title=a['title'],subtitle=a['skill'],minutes=20,lesson=a['lesson']+['ด่านนี้ดัดแปลงจากแนวทางในคู่มือครู ใช้โจทย์และข้อมูลสมมติที่สร้างใหม่สำหรับเรียนด้วยตนเอง'],example=a['example'],activity=a['reflection'],reward=f"ตราภารกิจ {a['code']}",mode=mode,mode_label=label,instructions=instructions,rationale=rationale,difficulty='กิจกรรมจากคู่มือ',objectives=[a['skill'],'อธิบายหลักฐานและสะท้อนคิดหลังทำภารกิจ'],prerequisite_id=last[unit],questions=questions,source={'activity':a['code'],'chapter':a['chapter'],'chapter_title':a['chapter_title'],'pdf_page':a['pdf_page'],'printed_pages':a['printed_pages'],'label':'คู่มือครู เทคโนโลยี ป.5 สสวท. ฉบับ e-book พ.ศ. 2566'},guide_activity=True,standard='ว 4.2 ป.5/'+{1:'1',2:'3 และ 5',3:'4',4:'2',5:'3 และ 5',6:'2',7:'5',8:'1',9:'3'}[a['chapter']]))
        last[unit]=offset
    return result
